11	// GroupNormSwish op_host — tiling calculation + EXEC_KERNEL_CMD launch
12	
13	#include <algorithm>
14	#include <cstdint>
15	
16	#include <torch/extension.h>
17	#include <torch/library.h>
18	
19	#include "torch_kernel_helper.h"
20	#include "tiling/platform/platform_ascendc.h"
21	
22	#include "aclrtlaunch_group_norm_swish.h"
23	
24	namespace ascend_kernel {
25	
26	std::vector<at::Tensor> group_norm_swish(
27	    const at::Tensor &input,
28	    int64_t num_groups,
29	    const at::Tensor &weight,
30	    const at::Tensor &bias,
31	    double eps,
32	    double swish_scale)
33	{
34	    // Input validation
35	    TORCH_CHECK(input.dim() >= 2, "input must have at least 2 dimensions");
36	    TORCH_CHECK(
37	        input.scalar_type() == at::kFloat || input.scalar_type() == at::kHalf ||
38	            input.scalar_type() == at::kBFloat16,
39	        "input must be float16, float32, or bfloat16");
40	    TORCH_CHECK(weight.dim() == 1, "weight must be 1D");
41	    TORCH_CHECK(bias.dim() == 1, "bias must be 1D");
42	    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
43	    TORCH_CHECK(weight.is_contiguous(), "weight must be contiguous");
44	    TORCH_CHECK(bias.is_contiguous(), "bias must be contiguous");
45	    TORCH_CHECK(
46	        static_cast<int64_t>(input.sizes()[1]) == num_groups,
47	        "input channel size must match weight/bias size");
48	    TORCH_CHECK(
49	        static_cast<int64_t>(weight.sizes()[0]) == static_cast<int64_t>(input.sizes()[1]),
50	        "weight shape mismatch");
51	    TORCH_CHECK(
52	        static_cast<int64_t>(bias.sizes()[0]) == static_cast<int64_t>(input.sizes()[1]),
53	        "bias shape mismatch");
54	    TORCH_CHECK(
55	        static_cast<int64_t>(input.sizes()[1]) % num_groups == 0,
56	        "input channel size must be divisible by num_groups");
57	
58	    int32_t N = static_cast<int32_t>(input.sizes()[0]);
59	    int32_t C = static_cast<int32_t>(input.sizes()[1]);
60	    int32_t spatialSize = 1;
61	    for (int i = 2; i < input.dim(); ++i) {
62	        spatialSize *= static_cast<int32_t>(input.sizes()[i]);
63	    }
64	    int32_t numGroups = static_cast<int32_t>(num_groups);
65	
66	    // Create output tensors
67	    at::Tensor output = at::empty_like(input);
68	    at::Tensor mean = at::empty({N, numGroups}, input.options());
69	    at::Tensor rstd = at::empty({N, numGroups}, input.options());
70	
71	    // dtype flag: 0=fp32, 1=fp16, 2=bf16
72	    int64_t dtypeFlag = 0;
73	    if (input.scalar_type() == at::kHalf) {
74	        dtypeFlag = 1;
75	    } else if (input.scalar_type() == at::kBFloat16) {
76	        dtypeFlag = 2;
77	    }
78	
79	    // Get platform info
80	    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
81	    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
82	    int32_t totalInstances = N * numGroups;
83	    int32_t usedCoreNum = std::min<int32_t>(static_cast<int32_t>(coreNum), totalInstances);
84	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
85	
86	    // All params as left values
87	    float epsVal = static_cast<float>(eps);
88	    float swishScaleVal = static_cast<float>(swish_scale);
89	
90	    EXEC_KERNEL_CMD(group_norm_swish, blockDim,
91	                    input, weight, bias, output, mean, rstd,
92	                    N, C, spatialSize, numGroups,
93	                    epsVal, swishScaleVal, dtypeFlag);
94	
95	    return {output, mean, rstd};
96	}
97	
