11	// AscendC GroupNormSwish kernel
12	// Supports float32, float16, bfloat16
13	// Input: [N, C, *spatial] -> each core processes (N, group) instances
14	// Output: [N, C, *spatial], mean [N, num_groups], rstd [N, num_groups]
15	//
16	// Algorithm per (n, g) instance:
17	//   1. Load x[n, c_start:c_end, :] into UB
18	//   2. Cast to float32 if needed
19	//   3. Compute mean = sum(x) / group_elements
20	//   4. Compute variance = sum((x - mean)^2) / group_elements
21	//   5. rstd = 1 / sqrt(var + eps)
22	//   6. Normalize: x_norm = (x - mean) * rstd
23	//   7. Apply weight and bias per-channel
24	//   8. Swish: output = x_norm * sigmoid(swish_scale * x_norm)
25	//   9. Write output, mean, rstd
26	
27	#include "kernel_operator.h"
28	
29	constexpr int32_t BUFFER_NUM = 2;
30	
31	// ---------------------------------------------------------------------------
32	// Inline helpers
33	// ---------------------------------------------------------------------------
34	
35	template <typename T>
36	__aicore__ inline void LoadGmToUb(
37	    AscendC::LocalTensor<T> &dst,
38	    AscendC::GlobalTensor<T> src,
39	    uint32_t count)
40	{
41	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
42	    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
43	    AscendC::DataCopyPad(dst, src, copyParams, padParams);
44	}
45	
46	template <typename T>
47	__aicore__ inline void StoreUbToGm(
48	    AscendC::GlobalTensor<T> dst,
49	    AscendC::LocalTensor<T> &src,
50	    uint32_t count)
51	{
52	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
53	    AscendC::DataCopyPad(dst, src, copyParams);
54	}
55	
56	template <typename T>
57	__aicore__ inline AscendC::RoundMode OutputRoundModeHelper()
58	{
59	    if constexpr (std::is_same_v<T, bfloat16_t>) {
60	        return AscendC::RoundMode::CAST_ROUND;
61	    }
62	    return AscendC::RoundMode::CAST_NONE;
63	}
64	
65	// =========================================================================
66	// GroupNormSwish Kernel
67	// =========================================================================
68	
69	template <typename dataType>
70	class GroupNormSwishKernel {
71	public:
72	    __aicore__ inline void Init(
73	        GM_ADDR x, GM_ADDR weight, GM_ADDR bias, GM_ADDR y, GM_ADDR mean, GM_ADDR rstd,
74	        int32_t N, int32_t C, int32_t spatialSize, int32_t numGroups,
75	        float eps, float swishScale, int64_t dtypeFlag)
76	    {
77	        this->N = N;
78	        this->C = C;
79	        this->spatialSize = spatialSize;
80	        this->numGroups = numGroups;
81	        this->channelsPerGroup = C / numGroups;
82	        this->groupElements = this->channelsPerGroup * spatialSize;
83	        this->totalInstances = N * numGroups;
84	        this->eps = eps;
85	        this->swishScale = swishScale;
86	        this->invGroupElements = 1.0f / static_cast<float>(this->groupElements);
87	
88	        int64_t totalElements = static_cast<int64_t>(N) * C * spatialSize;
89	        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x), totalElements);
90	        weightGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(weight), C);
91	        biasGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(bias), C);
92	        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), totalElements);
93	        meanGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(mean), N * numGroups);
94	        rstdGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(rstd), N * numGroups);
95	
96	        if ASCEND_IS_AIV {
97	            InitAivBuffers();
98	        }
99	    }
100	
101	    __aicore__ inline void InitAivBuffers()
102	    {
103	        tileSize_ = groupElements;
104	
105	        // Input/output queues
106	        pipe.InitBuffer(xInQueue_, BUFFER_NUM, tileSize_ * sizeof(dataType));
107	        pipe.InitBuffer(yOutQueue_, BUFFER_NUM, tileSize_ * sizeof(dataType));
108	        pipe.InitBuffer(meanOutQueue_, BUFFER_NUM, sizeof(dataType));
109	        pipe.InitBuffer(rstdOutQueue_, BUFFER_NUM, sizeof(dataType));
110	
111	        // Weight/bias queues (small, per-channel)
112	        pipe.InitBuffer(wInQueue_, BUFFER_NUM, channelsPerGroup * sizeof(dataType));
113	        pipe.InitBuffer(bInQueue_, BUFFER_NUM, channelsPerGroup * sizeof(dataType));
114	
115	        // Computation buffers (float32)
116	        pipe.InitBuffer(xFloatBuf_, tileSize_ * sizeof(float));
117	        pipe.InitBuffer(xNormBuf_, tileSize_ * sizeof(float));
118	        pipe.InitBuffer(outFloatBuf_, tileSize_ * sizeof(float));
119	        pipe.InitBuffer(wFloatBuf_, channelsPerGroup * sizeof(float));
120	        pipe.InitBuffer(bFloatBuf_, channelsPerGroup * sizeof(float));
121	        pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
122	        pipe.InitBuffer(meanRstdBuf_, 2 * sizeof(float));
123	        pipe.InitBuffer(reduceTmpBuf_, 2 * tileSize_ * sizeof(uint8_t));
124	
125	        if constexpr (!std::is_same_v<dataType, float>) {
126	            pipe.InitBuffer(xCastBuf_, tileSize_ * sizeof(float));
127	            pipe.InitBuffer(yCastBuf_, tileSize_ * sizeof(float));
128	            pipe.InitBuffer(wCastBuf_, channelsPerGroup * sizeof(float));
129	            pipe.InitBuffer(bCastBuf_, channelsPerGroup * sizeof(float));
130	        }
131	    }
132	
133	    __aicore__ inline void Process()
134	    {
135	        if ASCEND_IS_AIV {
136	            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
137	            const int subBlockIdx = AscendC::GetSubBlockIdx();
138	            const int numSubBlocks = AscendC::GetSubBlockNum();
139	            const int totalCores = usedCoreNum_ * numSubBlocks;
140	            const int coreOffset = coreIdx * numSubBlocks + subBlockIdx;
141	
142	            for (int instIdx = coreOffset; instIdx < totalInstances; instIdx += totalCores) {
143	                ProcessInstance(instIdx);
144	            }
145	        }
146	    }
147	
148	private:
149	    __aicore__ inline void ProcessInstance(int32_t instIdx)
150	    {
151	        int32_t nIdx = instIdx / numGroups;
152	        int32_t gIdx = instIdx % numGroups;
153	        int32_t cStart = gIdx * channelsPerGroup;
154	
155	        // Load input for this group
156	        int64_t xOffset = static_cast<int64_t>(nIdx) * C * spatialSize + static_cast<int64_t>(cStart) * spatialSize;
157	        LoadInput(xOffset);
158	
159	        // Load weight and bias for this group
160	        LoadWeightBias(cStart);
161	
162	        // Cast input to float32
