206	    __aicore__ inline float ComputeMean()
207	    {
208	        AscendC::LocalTensor<float> sumLocal = sumBuf_.Get<float>();
209	        AscendC::LocalTensor<uint8_t> reduceTmp = reduceTmpBuf_.Get<uint8_t>();
210	        const uint32_t reduceShape[2] = {1, static_cast<uint32_t>(tileSize_)};
211	        AscendC::ReduceSum<float, AscendC::Pattern::Reduce::AR, false>(
212	            sumLocal, xFloatLocal_, reduceTmp, reduceShape, true);
213	        float totalSum = sumLocal.GetValue(0);
214	        return totalSum * invGroupElements;
215	    }
