217	    __aicore__ inline float ComputeRstd(float meanVal)
218	    {
219	        // xNorm = x - mean
220	        AscendC::LocalTensor<float> xNorm = xNormBuf_.Get<float>();
221	        AscendC::Adds(xNorm, xFloatLocal_, -meanVal, tileSize_);
222	
223	        // var = sum(xNorm^2) / groupElements
224	        AscendC::LocalTensor<float> xNormSq = xNormBuf_.Get<float>();
225	        AscendC::Mul(xNormSq, xNorm, xNorm, tileSize_);
226	
227	        AscendC::LocalTensor<float> sumLocal = sumBuf_.Get<float>();
228	        AscendC::LocalTensor<uint8_t> reduceTmp = reduceTmpBuf_.Get<uint8_t>();
229	        const uint32_t reduceShape[2] = {1, static_cast<uint32_t>(tileSize_)};
230	        AscendC::ReduceSum<float, AscendC::Pattern::Reduce::AR, false>(
231	            sumLocal, xNormSq, reduceTmp, reduceShape, true);
232	        float varSum = sumLocal.GetValue(0);
233	        float varVal = varSum * invGroupElements;
234	        float varEps = varVal + eps;
235	
236	        // rstd = 1 / sqrt(varEps)
237	        AscendC::LocalTensor<float> mrBuf = meanRstdBuf_.Get<float>();
238	        AscendC::Duplicate(mrBuf, varEps, 1);
239	        AscendC::Rsqrt(mrBuf, mrBuf, 1);
240	        AscendC::PipeBarrier<PIPE_ALL>();
241	        float rstdVal = mrBuf.GetValue(0);
242	        AscendC::PipeBarrier<PIPE_ALL>();
243	
244	        return rstdVal;
245	    }
