247	    __aicore__ inline void ComputeOutput(float meanVal, float rstdVal, int32_t cStart)
248	    {
249	        // xNorm = (x - mean) * rstd
250	        AscendC::LocalTensor<float> xNorm = xNormBuf_.Get<float>();
251	        AscendC::Adds(xNorm, xFloatLocal_, -meanVal, tileSize_);
252	
253	        AscendC::LocalTensor<float> outFloat = outFloatBuf_.Get<float>();
254	        AscendC::Muls(outFloat, xNorm, rstdVal, tileSize_);
255	
256	        // Cast weight and bias to float32
257	        wInLocal_ = wInQueue_.DeQue<dataType>();
258	        bInLocal_ = bInQueue_.DeQue<dataType>();
