265	            bFloatLocal_ = bCastBuf_.Get<float>();
266	            AscendC::Cast(wFloatLocal_, wInLocal_, AscendC::RoundMode::CAST_NONE, channelsPerGroup);
267	            AscendC::Cast(bFloatLocal_, bInLocal_, AscendC::RoundMode::CAST_NONE, channelsPerGroup);
268	        }
269	
270	        // Apply weight and bias per-channel (broadcast along spatial dimension)
271	        // For each channel c in [0, channelsPerGroup):
272	        //   for each spatial s in [0, spatialSize):
273	        //     idx = c * spatialSize + s
274	        //     out[idx] = out[idx] * weight[c] + bias[c]
275	        //
276	        // Since we can't do nested loops efficiently, we use vector operations.
277	        // We broadcast weight[c] to all spatial positions using Duplicate + Muls
278	        // But this is complex. Instead, we process channel by channel with scalar weight/bias.
279	
280	        // For efficiency with vector ops: use Muls/Adds with scalar per channel
281	        // Process each channel's spatial slice
282	        for (int c = 0; c < channelsPerGroup; ++c) {
283	            float wVal = wFloatLocal_.GetValue(c);
284	            float bVal = bFloatLocal_.GetValue(c);
285	            int offset = c * spatialSize;
286	
287	            // out[offset:offset+spatialSize] = out[offset:offset+spatialSize] * wVal + bVal
288	            // Use Muls then Adds with scalar
289	            AscendC::Muls(outFloat[offset], outFloat[offset], wVal, spatialSize);
290	            AscendC::Adds(outFloat[offset], outFloat[offset], bVal, spatialSize);
291	        }
292	
293	        // Swish activation: x * sigmoid(swish_scale * x)
294	        // sigmoid(x) = 1 / (1 + exp(-x))
295	        // First: swish_input = swish_scale * out
296	        AscendC::Muls(outFloat, outFloat, swishScale, tileSize_);
297	
298	        // sigmoid = 1 / (1 + exp(-swish_input))
299	        // = exp(swish_input) / (1 + exp(swish_input))
300	        // Or compute directly: exp(-x), add 1, reciprocal
301	        AscendC::Muls(xNorm, outFloat, -1.0f, tileSize_);  // xNorm = -swish_input (reuse buffer)
302	        AscendC::Exp(xNorm, xNorm, tileSize_);             // xNorm = exp(-swish_input)
303	        AscendC::Adds(xNorm, xNorm, 1.0f, tileSize_);     // xNorm = 1 + exp(-swish_input)
304	        AscendC::Reciprocal(xNorm, xNorm, tileSize_);      // xNorm = sigmoid(swish_input)
305	
306	        // out = original_out * sigmoid
307	        // But we overwrote outFloat with swish_input! Need to recompute or save.
308	        // Let's restructure: save swish_input in xNorm, compute sigmoid in outFloat, then multiply
309	
310	        // Actually, let me redo this more carefully:
311	        // Step 1: swish_input = swish_scale * out  -> store in xNorm
312	        // Step 2: sigmoid = 1 / (1 + exp(-swish_input)) -> compute in outFloat
313	        // Step 3: out = out * sigmoid
314	        // But out was overwritten in step 1. Need to save original.
315	
316	        // Let me fix this:
317	        // Save original normalized output before swish
318	        // Then compute swish and multiply
319	
320	        // For now, recompute: the normalized output before swish was:
321	        // x_norm * rstd * weight + bias
322	        // But we overwrote it. We need to recompute from xNormBuf_.
323	
324	        // SIMPLER: redo normalization and weight/bias application
325	        // This is wasteful but correct for now
326	        // TODO: optimize by saving intermediate result
327	
328	        // Recompute normalized output
329	        AscendC::Adds(xNorm, xFloatLocal_, -meanVal, tileSize_);
330	        AscendC::Muls(outFloat, xNorm, rstdVal, tileSize_);
331	
332	        // Reapply weight and bias
333	        for (int c = 0; c < channelsPerGroup; ++c) {
334	            float wVal = wFloatLocal_.GetValue(c);
335	            float bVal = bFloatLocal_.GetValue(c);
336	            int offset = c * spatialSize;
337	            AscendC::Muls(outFloat[offset], outFloat[offset], wVal, spatialSize);
338	            AscendC::Adds(outFloat[offset], outFloat[offset], bVal, spatialSize);
339	        }
340	
341	        // Now compute swish properly
342	        // Save normalized output to xNorm
343	        AscendC::DataCopy(xNorm, outFloat, tileSize_);
344	
345	        // swish_input = swish_scale * out
346	        AscendC::Muls(outFloat, outFloat, swishScale, tileSize_);
347	
348	        // sigmoid = 1 / (1 + exp(-swish_input))
349	        AscendC::Muls(outFloat, outFloat, -1.0f, tileSize_);
350	        AscendC::Exp(outFloat, outFloat, tileSize_);
351	        AscendC::Adds(outFloat, outFloat, 1.0f, tileSize_);
352	        AscendC::Reciprocal(outFloat, outFloat, tileSize_);
353	
354	        // out = normalized_out * sigmoid
355	        AscendC::Mul(outFloat, xNorm, outFloat, tileSize_);
356	
357	        wInQueue_.FreeTensor(wInLocal_);
358	        bInQueue_.FreeTensor(bInLocal_);
359	    }
