11	// AscendC GroupNormSwish kernel
12	// Supports float32, float16, bfloat16
13	// Input: [N, C, *spatial] -> each core processes (N, group) instances
14	// Output: [N, C, *spatial], mean [N, num_groups], rstd [N, num_groups]
15	//
16	// Algorithm per (n, g) instance:
17	//   1. Load x[n, c_start:c_end, :] into UB
18	//   2. Cast to float32 if needed
19	//   3. Compute mean = sum(x) / group_elements
20	//   4. Compute variance = sum((x - mean)^2) / group_elements
21	//   5. rstd = 1 / sqrt(var + eps)
22	//   6. Normalize: x_norm = (x - mean) * rstd
23	//   7. Apply weight and bias per-channel
24	//   8. Swish: output = x_norm * sigmoid(swish_scale * x_norm)
25	//   9. Write output, mean, rstd
26	
27	#include "kernel_operator.h"
28	
29	constexpr int32_t BUFFER_NUM = 1;
30	
31	// ---------------------------------------------------------------------------
32	// Inline helpers
33	// ---------------------------------------------------------------------------
34	
35	template <typename T>
36	__aicore__ inline void LoadGmToUb(
37	    AscendC::LocalTensor<T> &dst,
38	    AscendC::GlobalTensor<T> src,
39	    uint32_t count)
40	{
41	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
42	    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
43	    AscendC::DataCopyPad(dst, src, copyParams, padParams);
44	}
