47	__aicore__ inline void StoreUbToGm(
48	    AscendC::GlobalTensor<T> dst,
49	    AscendC::LocalTensor<T> &src,
50	    uint32_t count)
51	{
52	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
53	    AscendC::DataCopyPad(dst, src, copyParams);
54	}
