66	// GroupNormSwish Kernel
67	// =========================================================================
68	
69	template <typename dataType>
70	class GroupNormSwishKernel {
71	public:
72	    __aicore__ inline void Init(
73	        GM_ADDR x, GM_ADDR weight, GM_ADDR bias, GM_ADDR y, GM_ADDR mean, GM_ADDR rstd,
74	        int32_t N, int32_t C, int32_t spatialSize, int32_t numGroups,
75	        float eps, float swishScale, int64_t dtypeFlag)
76	    {
77	        this->N = N;
78	        this->C = C;
79	        this->spatialSize = spatialSize;
80	        this->numGroups = numGroups;
81	        this->channelsPerGroup = C / numGroups;
82	        this->groupElements = this->channelsPerGroup * spatialSize;
83	        this->totalInstances = N * numGroups;
84	        this->eps = eps;
85	        this->swishScale = swishScale;
86	        this->invGroupElements = 1.0f / static_cast<float>(this->groupElements);
87	
88	        int64_t totalElements = static_cast<int64_t>(N) * C * spatialSize;
89	        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x), totalElements);
90	        weightGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(weight), C);
91	        biasGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(bias), C);
92	        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), totalElements);
93	        meanGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(mean), N * numGroups);
94	        rstdGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(rstd), N * numGroups);
95	
96	        if ASCEND_IS_AIV {
97	            InitAivBuffers();
98	        }
99	    }
100	
101	    __aicore__ inline void InitAivBuffers()
102	    {
103	        tileSize_ = groupElements;
104	
105	        // Input/output queues
106	        pipe.InitBuffer(xInQueue_, BUFFER_NUM, tileSize_ * sizeof(dataType));
107	        pipe.InitBuffer(yOutQueue_, BUFFER_NUM, tileSize_ * sizeof(dataType));
108	        pipe.InitBuffer(meanOutQueue_, BUFFER_NUM, sizeof(dataType));
109	        pipe.InitBuffer(rstdOutQueue_, BUFFER_NUM, sizeof(dataType));
110	
111	        // Weight/bias queues (small, per-channel)
112	        pipe.InitBuffer(wInQueue_, BUFFER_NUM, channelsPerGroup * sizeof(dataType));
113	        pipe.InitBuffer(bInQueue_, BUFFER_NUM, channelsPerGroup * sizeof(dataType));
114	
115	        // Computation buffers (float32) - only allocate what's actually used
116	        pipe.InitBuffer(xNormBuf_, tileSize_ * sizeof(float));
117	        pipe.InitBuffer(outFloatBuf_, tileSize_ * sizeof(float));
118	        pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
119	        pipe.InitBuffer(meanRstdBuf_, 2 * sizeof(float));
120	        pipe.InitBuffer(reduceTmpBuf_, 2 * tileSize_ * sizeof(uint8_t));
121	
122	        if constexpr (!std::is_same_v<dataType, float>) {
123	            pipe.InitBuffer(xCastBuf_, tileSize_ * sizeof(float));
124	            pipe.InitBuffer(yCastBuf_, tileSize_ * sizeof(float));
125	            pipe.InitBuffer(wCastBuf_, channelsPerGroup * sizeof(float));
126	            pipe.InitBuffer(bCastBuf_, channelsPerGroup * sizeof(float));
127	        }
128	    }
129	
130	    __aicore__ inline void Process()
131	    {
132	        if ASCEND_IS_AIV {
133	            const int coreIdx = AscendC::GetBlockIdx();
134	            const int totalCores = AscendC::GetBlockNum();
135	
136	            for (int instIdx = coreIdx; instIdx < totalInstances; instIdx += totalCores) {
137	                ProcessInstance(instIdx);
138	            }
139	        }
140	    }
141	
142	private:
143	    __aicore__ inline void ProcessInstance(int32_t instIdx)
144	    {
145	        int32_t nIdx = instIdx / numGroups;
146	        int32_t gIdx = instIdx % numGroups;
147	        int32_t cStart = gIdx * channelsPerGroup;
148	
149	        // Load input for this group
150	        int64_t xOffset = static_cast<int64_t>(nIdx) * C * spatialSize + static_cast<int64_t>(cStart) * spatialSize;
151	        LoadInput(xOffset);
152	
153	        // Load weight and bias for this group
154	        LoadWeightBias(cStart);
155	
156	        // Cast input to float32
157	        xInLocal_ = xInQueue_.DeQue<dataType>();
158	        if constexpr (std::is_same_v<dataType, float>) {
159	            xFloatLocal_ = xInLocal_.template ReinterpretCast<float>();
160	        } else {
161	            xFloatLocal_ = xCastBuf_.Get<float>();
162	            AscendC::Cast(xFloatLocal_, xInLocal_, AscendC::RoundMode::CAST_NONE, tileSize_);
163	            AscendC::PipeBarrier<PIPE_V>();
164	        }
165	
166	        // Compute mean
167	        float meanVal = ComputeMean();
168	
169	        // Compute rstd
170	        float rstdVal = ComputeRstd(meanVal);
171	
172	        // Normalize, apply weight/bias, Swish
173	        ComputeOutput(meanVal, rstdVal, cStart);
174	
175	        // Store output
176	        StoreOutput(nIdx, cStart);
177	
178	        // Store mean and rstd
179	        StoreMeanRstd(nIdx, gIdx, meanVal, rstdVal);
180	
181	        xInQueue_.FreeTensor(xInLocal_);
182	    }
183	
184	    __aicore__ inline void LoadInput(int64_t offset)
185	    {
186	        xInLocal_ = xInQueue_.AllocTensor<dataType>();
187	        LoadGmToUb(xInLocal_, xGM_[offset], static_cast<uint32_t>(tileSize_));
188	        xInQueue_.EnQue(xInLocal_);
189	    }
190	
191	    __aicore__ inline void LoadWeightBias(int32_t cStart)
192	    {
193	        wInLocal_ = wInQueue_.AllocTensor<dataType>();
194	        bInLocal_ = bInQueue_.AllocTensor<dataType>();
