// AscendC GroupNormSwish kernel — minimal test version
// First verify basic data transport: copy input → output, zeros for mean/rstd

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;

// =========================================================================
// GroupNormSwish Kernel (minimal test)
// =========================================================================

template <typename dataType>
class GroupNormSwishKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR weight, GM_ADDR bias, GM_ADDR y, GM_ADDR mean, GM_ADDR rstd,
        int32_t N, int32_t C, int32_t spatialSize, int32_t numGroups,
        float eps, float swishScale, int64_t dtypeFlag)
    {
        this->N = N;
        this->C = C;
        this->spatialSize = spatialSize;
        this->numGroups = numGroups;
        this->channelsPerGroup = C / numGroups;
        this->groupElements = this->channelsPerGroup * spatialSize;
        this->totalInstances = N * numGroups;

        int64_t totalElements = static_cast<int64_t>(N) * C * spatialSize;
        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x), totalElements);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), totalElements);
        meanGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(mean), N * numGroups);
        rstdGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(rstd), N * numGroups);

        if ASCEND_IS_AIV {
            pipe.InitBuffer(inQueue_, 1, groupElements * sizeof(dataType));
            pipe.InitBuffer(outQueue_, 1, groupElements * sizeof(dataType));
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int coreIdx = AscendC::GetBlockIdx();
            const int totalCores = AscendC::GetBlockNum();

            for (int instIdx = coreIdx; instIdx < totalInstances; instIdx += totalCores) {
                int32_t nIdx = instIdx / numGroups;
                int32_t gIdx = instIdx % numGroups;
                int32_t cStart = gIdx * channelsPerGroup;

                // Copy input → output (identity)
                int64_t offset = static_cast<int64_t>(nIdx) * C * spatialSize + static_cast<int64_t>(cStart) * spatialSize;

                AscendC::LocalTensor<dataType> inLocal = inQueue_.AllocTensor<dataType>();
                AscendC::DataCopyParams copyParams{1, static_cast<uint16_t>(groupElements * sizeof(dataType)), 0, 0};
                AscendC::DataCopy(inLocal, xGM_[offset], copyParams);
                inQueue_.EnQue(inLocal);

                AscendC::LocalTensor<dataType> inData = inQueue_.DeQue<dataType>();
                AscendC::LocalTensor<dataType> outLocal = outQueue_.AllocTensor<dataType>();
                AscendC::DataCopyParams outCopyParams{1, static_cast<uint16_t>(groupElements * sizeof(dataType)), 0, 0};
                AscendC::DataCopy(outLocal, inData, outCopyParams);
                outQueue_.EnQue(outLocal);

                AscendC::LocalTensor<dataType> outData = outQueue_.DeQue<dataType>();
                AscendC::DataCopy(yGM_[offset], outData, copyParams);
                outQueue_.FreeTensor(outData);
                inQueue_.FreeTensor(inData);

                // Write mean = 0, rstd = 0
                int64_t mrOffset = static_cast<int64_t>(nIdx) * numGroups + gIdx;
                AscendC::LocalTensor<float> zeroVal = meanGM_[mrOffset];
                zeroVal.SetValue(0.0f);
            }
        }
    }

private:
    int32_t N = 0;
    int32_t C = 0;
    int32_t spatialSize = 0;
    int32_t numGroups = 0;
    int32_t channelsPerGroup = 0;
    int32_t groupElements = 0;
    int32_t totalInstances = 0;

    AscendC::GlobalTensor<dataType> xGM_;
    AscendC::GlobalTensor<dataType> yGM_;
    AscendC::GlobalTensor<float> meanGM_;
    AscendC::GlobalTensor<float> rstdGM_;

    AscendC::TQue<AscendC::TPosition::VECIN, 1> inQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, 1> outQueue_;
    AscendC::TPipe pipe;
};

